        for partition in range(partitions):
            p = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            if color:
                p.pty = True
            varargs_slice = varargs[partition * _max_length: (partition + 1) * _max_length]
            input_str = " ".join(varargs_slice).encode()
            output = p.communicate(input=input_str, timeout=1)
            if output[0]:
                yield output[0].decode().strip()
            if output[1]:
                yield output[1].decode().strip()
    except Exception as e:
        raise ValueError(f"Invalid xargs input! {e}")

