def extostr(cls, e, max_level=30, max_path_level=5):
        if not isinstance(e, Exception):
            raise TypeError("Parameter 'e' must be an exception instance, not {}.".format(type(e).__name__))
        if max_level < 1 or not isinstance(max_level, int):
            raise ValueError("Parameter 'max_level' must be a positive integer.")
        if max_path_level < 1 or not isinstance(max_path_level, int):
            raise ValueError("Parameter 'max_level' must be a positive integer.")

        trace = traceback.format_exc()
        stack = trace.split("\n")

        if len(stack) > max_level:
            stack = stack[-max_level:]

        indentation = " " * 4
        clean_stack = []
        for line in stack:
            if line.startswith("  File "):
                line = line.strip()
                line = line.replace(
                    os.path.dirname(os.path.abspath(__file__)),
                    "",
                )
                clean_stack.append(line)

        stack = ", ".join(clean_stack)

        if len(stack) > max_path_level:
            stack = stack[:max_path_level] + "..."

        return e.__class__.__name__ + ": " + str(e) + "\n" + stack

