def integral(bins, edges):
    if not (np.all(edges.size == bins.size + 1) and np.all(edges == bins[1:] + edges[0])):
        raise ValueError("Invalid bins and edges provided.")

    midpoints = (edges[1:] + edges[:-1]) / 2
    widths = edges[1:] - edges[:-1]
    return np.sum(np.sum(widths * midpoints * bins))

def integral(bins, edges):
    if len(bins) != len(edges) - 1:
        raise ValueError("edges must contain len(bins) + 1 elements")
    result = 0.
    for i in range(len(bins)):
        result += bins[i] * (edges[i + 1] - edges[i])
    return result

def integral(bins, edges):
    \"""Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    \"""
    if not isinstance(bins, list):
        raise ValueError("Expected argument bins to be list")
    if not isinstance(edges, list):
        raise ValueError("Expected argument edges to be list")
    if len(bins) != len(edges) + 1:
        raise ValueError("Expected bins to have length equal to edges + 1")
    return sum(bins) / len(bins)

