def format(self, sql, params):
    if isinstance(sql, str) or isinstance(sql, bytes):
        # Convert the SQL query to use the out-style parameters
        # instead of the in-style parameters
        query = sql.replace("?", ":")
        formatted_params = {}
        for key, value in params.items():
            formatted_params[f":{key}"] = value
        return query, formatted_params
    else:
        raise ValueError("sql must be a str or bytes")

def format(sql: AnyStr, params: Union[Dict[Union[str, int], Any], Sequence[Any]]) -> Tuple[AnyStr, Union[Dict[Union[str, int], Any], Sequence[Any]]]:
    formatted_sql = sql
    if isinstance(formatted_sql, str):
        formatted_sql = formatted_sql.replace("?", "%s")
    if isinstance(params, dict):
        converted_params = {str(k): v for k, v in params.items()}
    elif isinstance(params, list):
        converted_params = {str(i): v for i, v in enumerate(params)}
    else:
        raise ValueError("'params' must be a dict or a list")
    return formatted_sql, converted_params

