    in_style = getattr(self, "SQLParams", {"in": {}, "out": {}, "style": {}}).get("style", {})
    if isinstance(in_style, dict):
        out_params = {k: v for k, v in enumerate(in_style.items())}
    elif isinstance(in_style, sequence):
        out_params = [v for v in in_style]
    else:
        raise ValueError("Invalid in-style parameter style. Must be either a dict or a sequence.")
