def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    digests_needed = set()
    for manifest_file in manifest_files:
        with open(manifest_file, "r") as f:
            for line in f:
                digest = line.split(":")[0].strip()
                if digest not in digests_used:
                    return False
                digests_needed.add(digest)
    return len(digests_needed) == len(set(digests_used))

def check_digests_present_and_used(self, manifest_files, digests_used):
    for manifest_file in manifest_files:
        with open(manifest_file, 'r') as f:
            manifest_contents = f.read()
        for digest in digests_used:
            if digest not in manifest_contents:
                raise Exception(f'Digest {digest} is not present in {manifest_file}.')
            if manifest_contents.count(digest) == 1:
                raise Exception(f'Digest {digest} is not used in {manifest_file}.')

