        for j, other_expr in enumerate(expr_list[i+1:]):
            if expr & other_expr == expr or expr | other_expr == expr:
                expr_list[j+i+1] = None
            elif ~expr & other_expr == expr or ~expr | other_expr == expr:
                expr_list[j+i+1] = None
                expr_list[i] = None
    return [expr for expr in expr_list if expr is not None]

def absorb(self, args):
    result = []
    for expr in args:
        if expr.operator == '|':
            new_expr = self._absorb(expr.left, expr.right)
            if new_expr is not None:
                result.append(new_expr)
        elif expr.operator == '&':
            new_expr = self._absorb(expr.right, expr.left)
            if new_expr is not None:
                result.append(new_expr)
        else:
            result.append(expr)
    return result

def on(self, hook):
    def register_handler(func):
        if not hasattr(hook, 'handlers'):
            hook.handlers = []
        hook.handlers.append(func)
        return func

    return register_handler

def on(self, hook):
    def decorator(handler):
        if hook not in handler:
            handler['hooks'] = [hook]
        else:
            handler['hooks'].append(hook)
        self.event_handlers.add(handler)
        return handler

    return decorator

def on(self, hook):
    def wrap(handler):
        if not callable(handler):
            raise TypeError("Handler must be a callable")
        self.hooks.setdefault(hook, []).append(handler)
        return handler
    return wrap

