def _fromutc(self, dt):
    tz = dt.tzinfo
    offset = tz.utcoffset(dt)
    new_offset = tz.dst(dt)
    if new_offset is None or new_offset == offset:
        return dt
    else:
        return dt.replace(tzinfo=tz)

def _fromutc(self, dt):
    if not isinstance(dt, datetime.datetime):
        raise TypeError("Expected datetime.datetime object, got {}".format(type(dt)))
    if dt.tzinfo is None:
        raise ValueError("Cannot calculate from naive datetimes")

    new_dt = dt.astimezone(self.tz)

    if not new_dt.dst():
        # Handle ambiguous datetimes
        if self.tz.dst(dt) and new_dt.utcoffset() != dt.utcoffset():
            new_dt -= datetime.timedelta(hours=1)

    return new_dt

def _fromutc(self, dt):
    if not isinstance(dt, datetime.datetime):
        raise ValueError("Input date must be a datetime.datetime object")

    tzinfo = dt.tzinfo
    if tzinfo is None:
        raise ValueError("Input date must have a timezone set")

    if self.key != tzinfo.key:
        # Convert to the new timezone
        dt = dt.astimezone(self)

    # Check if the datetime is ambiguous and in a "fold" state
    dt_lower = dt.replace(fold=1)
    dt_upper = dt.replace(fold=0)

    matching_ambig_utc_dt = self.utc(dt_lower)

    if matching_ambig_utc_dt is not None:
        # Raise an AmbiguousTimeError if the datetime is ambiguous
        raise AmbiguousTimeError(
            f"Ambiguous time: {dt} could map to {dt_lower} or {dt_upper}"
        )

    return dt

