def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Ensure the `commands` parameter is a list
    if not isinstance(commands, list):
        raise ValueError("The `commands` parameter must be a list")

    # Ensure the `args` parameter is a list
    if not isinstance(args, list):
        raise ValueError("The `args` parameter must be a list")

    # Ensure the `cwd` parameter is a string or None
    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("The `cwd` parameter must be a string or None")

    # Ensure the `verbose` parameter is a bool
    if not isinstance(verbose, bool):
        raise ValueError("The `verbose` parameter must be a bool")

    # Ensure the `hide_stderr` parameter is a bool
    if not isinstance(hide_stderr, bool):
        raise ValueError("The `hide_stderr` parameter must be a bool")

    # Ensure the `env` parameter is a dictionary or None
    if env is not None and not isinstance(env, dict):
        raise ValueError("The `env` parameter must be a dictionary or None")

    # Run the commands
    for command in commands:
        try:
            # Print the command if `verbose` is True
            if verbose:
                print(f"Running command: '{command}'")

            # Build the subprocess command
            proc = subprocess.run(
                [str(command), *args],
                cwd=cwd,
                check=True,
                shell=True,
                stderr=subprocess.DEVNULL if hide_stderr else None,
                env=env,
            )

            # Return the subprocess output
            return proc.stdout.decode()
        except subprocess.CalledProcessError as e:
            # Print the stderr output if `verbose` is True
            if verbose and e.stderr is not None:
                print(f"Error occurred: '{e.stderr.decode()}'")

            # Raise the exception
            raise e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    # Validate and preprocess inputs
    if not commands:
        raise ValueError("'commands' must not be an empty list")
    if not isinstance(commands, list):
        raise TypeError("'commands' must be a list")
    if not isinstance(args, list):
        raise TypeError("'args' must be a list")
    if cwd and not isinstance(cwd, str):
        raise TypeError("'cwd' must be a string or None")
    if env and not isinstance(env, dict):
        raise TypeError("'env' must be a dict or None")

    # Set the keyword arguments
    kwargs = {
        "env": None,
        "cwd": None,
        "shell": True,
        "capture_output": True,
        "text": True,
        "input": None,
        "stdout": None,
        "stderr": None,
    }
    if verbose:
        kwargs["capture_output"] = False
    if hide_stderr:
        kwargs["stderr"] = subprocess.DEVNULL
    if cwd:
        kwargs["cwd"] = cwd
    if env:
        kwargs["env"] = env

    # Run the command
    try:
        result = subprocess.run(commands, args, **kwargs, check=True)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(
            f"Process exited with {exc.returncode}:\n{exc.output.decode()}"
        ) from exc

    # Return the result
    return result

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    if not isinstance(commands, (list, tuple)):
        commands = (commands,)

    for command in commands:
        if not isinstance(command, str):
            raise ValueError("Invalid command: {}".format(command))

    if not isinstance(args, list):
        raise ValueError("args must be a list")

    for arg in args:
        if not isinstance(arg, str):
            raise ValueError("Arg must be a string: {}".format(arg))

    # Create the command-line string
    command_line = [command] + args

    if cwd is not None and not isinstance(cwd, str):
        raise ValueError("cwd must be a string")

    if verbose:
        print("Running command: '{}'".format(" ".join(command_line)))

    # Run the command
    try:
        result = subprocess.run(command_line, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env)
    except subprocess.CalledProcessError as e:
        raise RuntimeError("Error running command '{}': {}".format(" ".join(command_line), e))

    # Return the output
    return result.stdout.decode("utf-8").strip()

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    # Validate input parameters
    if not isinstance(commands, (list, tuple)):
        raise ValueError("commands must be a list or tuple")
    elif not isinstance(args, dict):
        raise ValueError("args must be a dictionary")
    elif not isinstance(cwd, (str, NoneType)):
        raise ValueError("cwd must be a string or None")
    elif not isinstance(verbose, bool):
        raise ValueError("verbose must be a boolean")
    elif not isinstance(hide_stderr, bool):
        raise ValueError("hide_stderr must be a boolean")
    elif not isinstance(env, (dict, NoneType)):
        raise ValueError("env must be a dictionary or None")

    # Build the command to run
    cmd = commands[0]
    for arg in args:
        cmd += f" {arg}={args[arg]}"
    for cmd_ in commands[1:]:
        cmd += f" {cmd_}"

    # Run the command
    proc = subprocess.Popen(cmd, cwd=cwd, env=env, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    out, err = proc.communicate()

    # Handle verbose mode
    if verbose:
        print(f"[INPUT]: {cmd}\n[OUTPUT]: {out.decode()}")
        if hide_stderr and err:
            print(f"[STDERR]: {err.decode()}")
        else:
            sys.stderr.write(err.decode())

    # Return the output
    return out.decode()

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    import subprocess
    import sys

    if not isinstance(commands, list):
        commands = [commands]

    if not isinstance(args, list):
        args = [args]

    for command in commands:
        if verbose:
            print(f"Running command: {command + [' '.join(args)]}")

        if cwd is not None:
            new_env = os.environ.copy()
            new_env["PYTHONIOENCODING"] = "utf-8"
            process = subprocess.Popen(command + args, cwd=cwd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=new_env)
        else:
            process = subprocess.Popen(command + args, stdout=subprocess.PIPE, stderr=subprocess.PIPE)

        output, stderr = process.communicate()

        if hide_stderr:
            stderr = ""

        if output:
            print(output.decode().strip())
        if stderr:
            print(stderr.decode().strip(), file=sys.stderr)

        if process.returncode != 0:
            raise subprocess.CalledProcessError(process.returncode, command)

