def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    # Validate storage root hierarchy
    num_objects = 0
    good_objects = 0

    # Iterate over all objects in the storage root
    for obj in self.storage_root:
        num_objects += 1
        if obj.is_valid():
            good_objects += 1
            if check_digests and not obj.validate_checksum():
                good_objects -= 1
                if show_warnings:
                    print("Warning: object {} has invalid checksum".format(obj.name))
    return num_objects, good_objects

