    if self.directory.exists():
        num_objects = 0
        good_objects = 0
        for dirpath, _, filenames in os.walk(self.directory.resolve()):
            for filename in filenames:
                path = os.path.join(dirpath, filename)
                if not show_warnings and filename.startswith("."):
                    continue
                if validate_objects and not self.validate_object(path):
                    raise ValueError(f"Invalid schema path: {path}")
                else:
                    good_objects += 1
                if check_digests and not self.check_digest(path):
                    raise ValueError(f"Invalid digest for path: {path}")
                num_objects += 1
        return num_objects, good_objects
    else:
        raise ValueError("Directory does not exist")

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    num_objects, good_objects = 0, 0
    try:
        for obj in self.root.iterdir():
            num_objects += 1
            # check digest if check_digests is True
            if check_digests and obj.digest != obj.calc_digest():
                if show_warnings:
                    print(f"Object {obj.name} has invalid digest")
                continue
            # validate objects if validate_objects is True
            if validate_objects and not obj.validate():
                if show_warnings:
                    print(f"Object {obj.name} failed validation")
                continue
            good_objects += 1
        return num_objects, good_objects
    except Exception as e:
        raise ValidationError(f"Validation encountered an error: {e}") from e

