def validate_version_inventories(version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    inventory_lookup = {}
    for version_dir in version_dirs:
        inventory_path = os.path.join(version_dir, "inventory.json")
        try:
            with open(inventory_path) as f:
                inventory_data = json.load(f)
        except FileNotFoundError:
            raise ValueError(f"No inventory found for version {version_dir}")
        inventory_lookup[version_dir] = inventory_data
        for content_digest in set(inventory_lookup.values()):
            if content_digest not in root_inventory:
                content_references = [version_dir for version_dir, inventory in inventory_lookup.items() if content_digest in inventory]
                content_references_str = ", ".join(content_references)
                raise ValueError(f"Content digest {content_digest} is not found in root inventory. Referenced by versions: {content_references_str}")
    return inventory_lookup

def validate_version_inventories(self, version_dirs):
    version_inventories = []
    for version_dir in version_dirs:
        inventory_path = os.path.join(self.dir, version_dir, "inventory.json")
        if not os.path.isfile(inventory_path):
            raise Exception(f"Missing inventory file for version {version_dir}.")
        inventory_data = json.load(inventory_path)
        if "contentDigests" not in inventory_data:
            raise Exception(f"Malformed inventory file for version {version_dir}.")
        if not version_inventories:
            version_inventories.append(inventory_data)
        elif inventory_data["contentDigests"] != version_inventories[0]["contentDigests"]:
            raise Exception(f"Inventory content digests differ for version {version_dir}.")
        else:
            version_inventories.append(inventory_data)
    return version_inventories

def validate_version_inventories(version_dirs):
    for version_dir in version_dirs:
        inventory = load_inventory(version_dir)
        if not inventory:
            raise InvalidInventoryError(version_dir)
        content_digests = [item['content_digest'] for item in inventory]
        if any(content_digest not in root_inventory for content_digest in content_digests):
            missing_digests = [content_digest for content_digest in content_digests if content_digest not in root_inventory]
            raise MissingContentError(version_dir, missing_digests)
        root_inventory_content = set(item['content_digest'] for item in root_inventory)
        inventory_content = set(item['content_digest'] for item in inventory)
        if root_inventory_content != inventory_content:
            extra_digests = root_inventory_content - inventory_content
            raise ExtraContentError(version_dir, extra_digests)

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    try:
        if path.endswith("0=* - Namaste"):
            return "root"
        elif path.endswith("0=* - Inventory"):
            return "object"
        else:
            return "file"
    except Exception:
        return "exception"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Args:
        path (str): The path to the OCFL storage root or object.

    Returns:
        str: The type of the thing at the given path, one of "root", "object", "file", or a string describing an error.

    Ref:
        https://ocfl.io/1.0/spec/#space-preservation
    """
    if not os.path.isdir(path):
        raise ValueError(f"Path is not a directory: {path}")

    for fn in get_ocfl_filenames(path):
        if os.path.isfile(fn):
            with open(fn, "rb") as f:
                s = f.read(4)
                if s == b"OCFL":
                    return "root"
                elif s == b"OCOP":
                    return "object"
                else:
                    return "file"

    return "file"

def find_path_type(path: str) -> str:
    path_type = ""
    if is_ocfl_storage_root(path):
        path_type = "root"
    elif is_ocfl_object(path):
        path_type = "object"
    else:
        path_type = "file"
    return path_type

