def size_to_bytes(size: str) -> int:
    units = {
        "B": 1,
        "K": 1000,
        "M": 1000000,
        "G": 1000000000,
        "T": 1000000000000,
    }
    size = size.upper()
    if not size.isdigit():
        num, unit = size[:-1], size[-1]
        if num.isdigit() and unit in units:
            return int(num) * units[unit]
        else:
            raise ValueError(f"Invalid size: {size}")
    else:
        return int(size)

def size_to_bytes(size: str) -> int:
    if not size:
        return 0

    if size.isdigit():
        return int(size)

    try:
        num, unit = size.split()
        num = float(num)
        if unit in ['K', 'KB', 'KiB']:
            return num * 1000
        elif unit in ['M', 'MB', 'MiB']:
            return num * 1000000
        elif unit in ['G', 'GB', 'GiB']:
            return num * 1000000000
        elif unit in ['T', 'TB', 'TiB']:
            return num * 1000000000000
        else:
            return 0
    except ValueError:
        return 0
    except TypeError:
        return 0

def size_to_bytes(size: str) -> int:
    pattern = r"^(\d+)([KMGTP]?)$"
    match = re.match(pattern, size)
    if match:
        number, unit = match.groups()
        factor = {"": 1, "K": 10**3, "M": 10**6, "G": 10**9, "T": 10**12, "P": 10**15}
        return int(number) * factor[unit.upper()]
    else:
        raise ValueError("Invalid input")

