def _dictsum(dicts):
    def _get_key_value(d, key):
        value = 0
        if key in d:
            value = d[key]
        return value

    keys = set()
    for d in dicts:
        keys = keys.union(d.keys())

    result = {}
    for key in keys:
        result[key] = sum([_get_key_value(d, key) for d in dicts])

    return result

