void _replace_url_args(string url, Dictionary<string, string> url_args)
{
    MatchCollection matches = Regex.Matches(url, @"\{.*?\}");
    int length = matches.Count;
    for (int i = 0; i < length; i++)
    {
        Match match = matches[i];
        string groupValue = match.Value;
        string key = groupValue.Substring(1, groupValue.Length - 2);
        if (url_args.ContainsKey(key))
        {
            url = url.Replace(groupValue, url_args[key]);
        }
        else
        {
            throw new ArgumentException($"url_args does not contain key {key}");
        }
    }
}

