def vertex3tuple(vertices):
    if len(vertices) < 3:
        raise ValueError("Polygon must have at least 3 vertices")
    polygons = []
    for i in range(len(vertices)):
        vertex = vertices[i]
        left = vertices[(i - 1) % len(vertices)]
        right = vertices[(i + 1) % len(vertices)]
        polygons.append((vertex, left, right))
    return polygons

def vertex3tuple(vertices):
    if len(vertices) < 3:
        raise ValueError("Expected at least 3 vertices, but got {len(vertices)}")

    tuples = []
    for i in range(len(vertices)):
        a, b, c = vertices[i], vertices[(i + 1) % len(vertices)], vertices[(i + 2) % len(vertices)]
        tuples.append((a, b, c))

    return tuples

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise ValueError("`number` must be an integer")
    if not isinstance(alphabet, Sequence):
        raise TypeError("`alphabet` must be a list or tuple")
    if len(alphabet) == 0:
        raise ValueError("`alphabet` must not be empty")
    if padding is not None and not isinstance(padding, int):
        raise ValueError("`padding` must be an integer if specified")

    result = []
    while number > 0:
        result.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)
    result.reverse()

    if padding is not None and len(result) < padding:
        result = [alphabet[0]] * (padding - len(result)) + result

    return "".join(result)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError(f"Parameter `number` must be an integer, not {type(number)}.")
    if not isinstance(alphabet, list):
        raise TypeError(f"Parameter `alphabet` must be a list, not {type(alphabet)}.")
    if len(alphabet) != len(set(alphabet)):
        raise ValueError("The alphabet must not contain duplicate characters.")

    if padding is not None and not isinstance(padding, int):
        raise TypeError(f"Parameter `padding` must be an integer, not {type(padding)}.")

    if number <= 0:
        return str(number)

    arr = list(alphabet)
    result = ""
    while number > 0:
        result = alphabet[number % len(alphabet)] + result
        number = number // len(alphabet)

    if padding is not None:
        result = str(number).zfill(padding) + result

    return result

def int_to_string(number: int, alphabet: list[str], padding: Optional[int] = None) -> str:
    if not isinstance(number, int):
        raise ValueError("Number must be an integer.")
    if not isinstance(alphabet, list):
        raise ValueError("Alphabet must be a list of strings.")
    if padding is not None and (not isinstance(padding, int) or padding < 0):
        raise ValueError("Padding must be a non-negative integer.")

    if number == 0:
        return "0"

    digits = []
    while number > 0:
        digits.append(alphabet[number % len(alphabet)])
        number //= len(alphabet)

    if padding is not None:
        while len(digits) < padding:
            digits.append("0")

    return "".join(reversed(digits))

