def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not isinstance(string, str):
        raise ValueError("'string' must be a string")
    if not isinstance(alphabet, List[str]):
        raise ValueError("'alphabet' must be a list of strings")
    if len(alphabet) < 2:
        raise ValueError("'alphabet' must have at least two elements")
    result = 0
    for i, ch in enumerate(reversed(string)):
        idx = alphabet.index(ch)
        result += idx * pow(len(alphabet), i)
    return result

