def find_roots(graph: graphlib.Graph, prop: URIRef, roots: Optional[Set["Node"]] = None) -> Set["Node"]:
    if roots is None:
        roots = set()

    # find all nodes that have no incoming edges for the given property
    no_incoming = {node for node in graph.nodes() if prop not in graph.pred[node]}

    # if no roots are given, find all nodes with no incoming edges
    if not roots:
        roots = no_incoming
    # else find all roots by removing nodes from `roots` that still have incoming edges
    else:
        for node in graph.nodes():
            if node in roots and prop in graph.pred[node]:
                roots.remove(node)

    # remove any nodes that still have outgoing edges for the given property
    for node in graph.nodes():
        if prop in graph.succ[node]:
            roots.remove(node)

    return roots

def find_roots(graph, prop, roots=None):
    if roots is None:
        roots = set()
    for node in graph.subjects(predicate=RDFS.subClassOf, object=None):
        if node not in roots:
            roots.add(node)
            roots |= find_roots(graph, prop, roots)
    return roots

