def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    configuration_files = {}
    parse_errors = []

    for config_filename in config_filenames:
        try:
            with open(config_filename, 'r') as file:
                configuration_files[config_filename] = json.load(file)
                file.close()
        except json.JSONDecodeError as err:
            parse_errors.append(logging.LogRecord(
                name=__name__, level=logging.ERROR, pathname=config_filename, lineno=err.lineno,
                msg=f"Parse error in {config_filename}: {err.msg}"
            ))

    if resolve_env:
        for filename, config in configuration_files.items():
            for key, value in config.items():
                if isinstance(value, str) and value.startswith('$'):
                    try:
                        config[key] = os.environ[value[1:]]
                    except KeyError:
                        parse_errors.append(logging.LogRecord(
                            name=__name__, level=logging.ERROR, pathname=filename, lineno=None,
                            msg=f"No environment variable defined for {value}"
                        ))

    if overrides is not None:
        for filename, config in configuration_files.items():
            if filename in overrides:
                config.update(overrides[filename])

    return configuration_files, parse_errors

