def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    tags = set()
    replaced_text = text
    code_blocks = text.split("\n")
    for code_block in code_blocks:
        if "```" in code_block:
            continue
        for word in code_block.split(" "):
            if word.startswith("&lt;"):
                tag = word[1:]
                tags.add(tag)
                if replacer:
                    replaced_text = replaced_text.replace(word, replacer(tag))
    return tags, replaced_text

def find_tags(text, replacer=None):
    tags = set()
    txt = text
    in_code_block = False
    for line in text.splitlines():
        if line.startswith("```"):
            in_code_block = not in_code_block
            continue
        if in_code_block:
            continue
        for word in line.split():
            if word.startswith("#"):
                tag = word[1:]
                if replacer:
                    tag = replacer(tag)
                tags.add(tag)
                txt = txt.replace(word, tag, 1)
    return tags, txt

def find_tags(text: str, replacer: Callable = None) -> Tuple[Set, str]:
    tags = set()
    lines = text.splitlines()
    in_code_block = False
    for line in lines:
        if line.startswith("```"):
            in_code_block = not in_code_block
            continue
        if in_code_block:
            continue
        for word in line.split():
            if word.startswith("#"):
                tag = word[1:]
                tags.add(tag)
                if replacer:
                    line = line.replace(word, replacer(tag))
    return tags, lines.join(line)

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    tag_start = False
    in_code_block = False
    replaced_text = ""

    for char in text:
        if char == "<":
            tag_start = True
        elif char == ">":
            tag_start = False

        if tag_start:
            tags.add(char)
        elif char == "```" and not in_code_block:
            in_code_block = True
        elif char == "```" and in_code_block:
            in_code_block = False

        if replacer:
            if tag_start:
                tag = char
            else:
                tag = ""
            replaced_text += replacer(tag)
        else:
            replaced_text += char

    return tags, replaced_text

def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    text = text + " "
    while True:
        start = text.find("<")
        if start == -1:
            break
        end = text.find(">", start + 1)
        if end == -1:
            break
        if text[start - 1] == "`" and text[end + 1] == "`":
            text = text[:start] + text[end + 2:]
            continue
        tag = text[start + 1:end]
        tags.add(tag)
        if replacer:
            text = text[:start] + replacer(tag) + text[end + 1:]
    return tags, text

