def dict_insert(dic: Dict[str, Any], val: Any, key: str, *keys: List[str]) -> Dict[str, Any]:
    if not keys:
        dic[key] = val
        return dic

    if key not in dic:
        dic[key] = {}

    return dict_insert(dic[key], val, *keys)

def dict_insert(dic, val, key, *keys):
    curr_key = key
    for curr_key, sub_key in zip(keys, keys[1:]):
        if curr_key not in dic:
            dic[curr_key] = {}
        elif not isinstance(dic[curr_key], dict):
            raise ValueError(f"Key `{curr_key}` is not a dictionary.")
        dic = dic[curr_key]
    dic[sub_key] = val
    return dic

def dict_insert(dic, val, key, *keys):
    if not isinstance(dic, dict):
        raise TypeError("'dic' should be a dictionary object")

    ancestor_keys = [key] + list(keys)
    current_key = None
    for key in ancestor_keys:
        value = None
