    """Create a new IniType complex type

    Args:
        settings_dirs (list): A list of directories to search for files
        spec_option (bool): Indicates whether to use special handling for special files

    Returns:
        list: A list of file names found in the search directories

    Raises:
        OSError: If an error occurs while searching for files
        ValueError: If the spec_option is not a boolean value
    """
    if not isinstance(spec_option, bool):
        raise ValueError("spec_option must be a boolean value.")
    file_names = []
    for directory in settings_dirs:
        if os.path.isdir(directory):
            for root, dirs, files in os.walk(directory):
                for file in files:
                    file_names.append(os.path.join(root, file))
        else:
            file_names.append(directory)
        if spec_option:
