                if re.search(r'(\.ini|\.INI)$', file):
                    yield file
    return file_names

def list_of_file_names(settings_dirs, spec_option):
    """Create a new list of file names from a list of directories and an option to specify which files to include.

    Arguments:
        settings_dirs {List[str]} -- A list of directories to search.
        spec_option {str} -- An optional specification for the files to include.

    Returns:
        List[str] -- A list of file names that match the search criteria.

    Raises:
        FileNotFoundError: If the specified directories are not valid.
        ValueError: If the provided specification is not valid.
    """
    if not settings_dirs:
        return []

    file_names = []
    for settings_dir in settings_dirs:
        if not os.path.isdir(settings_dir):
            raise FileNotFoundError("Directory '{}' does not exist.".format(settings_dir))
        for root, _, files in os.walk(settings_dir):
            for f in files:
                if spec_option and not re.match(spec_option, f):
                    continue
                file_names.append(os.path.join(root, f))
    return file_names

def list_of_file_names(settings_dirs, spec_option):
    if not settings_dirs or not spec_option:
        raise ValueError("Both settings_dirs and spec_option are required")

    file_names = []
    for dir in settings_dirs:
        for path in Path(dir).glob("*/"):
            if path.is_dir():
                file_name = Path(path).name
                if file_name.startswith(spec_option):
                    file_names.append(file_name)

    return sorted(file_names)

