def get_nested_custom_and_control_args(self, args) -> Tuple[Dict, Dict]:
    control_args = {}
    nested_args = {}

    for arg in args:
        if arg.startswith("--"):
            control_args[arg] = arg

    for arg in args:
        if arg.startswith("--") and arg not in control_args.keys():
            nested_args[arg] = arg

    for arg in args:
