def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    try:
        # Make sure the workspace is valid
        if ir_workspace is None or ir_workspace.is_valid() is False:
            raise ValueError("Invalid Infrared Workspace")

        # Make sure the plugin is valid
        if ir_plugin is None or ir_plugin.is_valid() is False:
            raise ValueError("Invalid Infrared Plugin")

        # Make sure the playbook path is valid
        if playbook_path is None or os.path.isfile(playbook_path) is False:
            raise ValueError("Invalid playbook path")

        # Build the Ansible command line arguments
        ansible_cmd_args = [
            "ansible-playbook",
            playbook_path,
            "-w" + f"{ir_workspace.id}",
            "-p" + f"{ir_plugin.id}"
        ]

        # Add extra vars if provided
        if extra_vars is not None:
            ansible_cmd_args.append("--extra-vars")
            ansible_cmd_args.append(extra_vars)

        # Add Ansible args if provided
        if ansible_args is not None:
            for ansible_arg in ansible_args:
                ansible_cmd_args.append(ansible_arg)

        # Run the Ansible command
        return subprocess.check_output(ansible_cmd_args)

    except Exception as e:
        raise RuntimeError("Failed to run Ansible playbook: " + str(e)) from None

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    cmd = ["ansible-playbook", playbook_path]
    if verbose:
        cmd.append("-" + str(verbose * 2))
    if extra_vars:
        cmd.append("--extra-vars")
        cmd.append(json.dumps(extra_vars))
    if ansible_args:
        cmd.extend(ansible_args)
    try:
        subprocess.run(cmd, check=True, env=ir_plugin.get_environment_variables())
    except subprocess.CalledProcessError as e:
        raise InfraredPlaybookExecutionError(f"Ansible playbook failed with exit code {e.returncode}") from e

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None, extra_vars=None, ansible_args=None):
    ir_playbook = find_active_playbook(ir_workspace, playbook_path)
    playbook_validator(ir_playbook, ir_plugin, ansible_args)

    ansible_args = add_ansible_args(ansible_args, ir_playbook, verbose, extra_vars)
    ansible_dir = ir_playbook.context.platform.ansible_dir

    return run_ansible(ir_workspace, ir_plugin, ansible_dir, ansible_args, verbose)

def run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    try:
        # Make sure vars_dict is a dict
        if not isinstance(vars_dict, dict):
            raise ValueError("Expected a dict for vars_dict, but got %s" % type(vars_dict).__name__)
        # Make sure cli_args is a list or tuple
        if not isinstance(cli_args, (list, tuple)):
            raise ValueError("Expected a list or tuple for cli_args, but got %s" % type(cli_args).__name__)
        # Make sure ir_workspace is an infrared workspace object
        if not isinstance(ir_workspace, infrared.workspace.Workspace):
            raise ValueError("Expected an Infrared Workspace object for ir_workspace, but got %s" % type(ir_workspace).__name__)
        # Make sure ir_plugin is an infrared plugin object
        if not isinstance(ir_plugin, infrared.plugin.Plugin):
            raise ValueError("Expected an Infrared Plugin object for ir_plugin, but got %s" % type(ir_plugin).__name__)
        # Run the playbook
        result = subprocess.run(cli_args, cwd=ir_workspace.path, env=ir_plugin.env, input=json.dumps(vars_dict).encode())
        # Return the ansible results
        return json.loads(result.stdout)
    except (subprocess.CalledProcessError, json.JSONDecodeError) as e:
        raise Exception("Error running playbook: %s" % e) from None

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    ansible_config = get_ansible_config()
    display = ir_workspace.env.get('IR_ANSIBLE_FULL_DISPLAY', '').lower() == 'true'

    ansible_args = ['ansible-playbook'] + cli_args
    ansible_args.extend(['-e', json.dumps({"classic_mode": False})])
    ansible_args.extend(['-e', json.dumps(vars_dict)])
    ansible_args.extend(['-e', json.dumps({"lkey": ir_plugin.local_lookup_key})])
    ansible_args.extend(['-e', json.dumps({"classic_editor": ir_plugin.editor})])

    if display:
        ansible_args.append("-vvvvvv")

    try:
        result = subprocess.run(ansible_args, capture_output=True)
    except subprocess.CalledProcessError as e:
        raise InfraredCommandError(f'Ansible error: {e.stderr.decode()}')

    return parse(result.stdout)

def _convert_non_cli_args(self, parser_name, values_dict):
    try:
        for arg_name, arg_value in values_dict.items():
            arg_type = getattr(self, f"_{parser_name}_{arg_name}_type")
            if arg_type is not None and arg_type != str:
                values_dict[arg_name] = arg_type(arg_value)
    except ValueError as e:
        raise argparse.ArgumentTypeError(str(e))

def _convert_non_cli_args(self, parser_name, values_dict):
    parser_name = str(parser_name).lower()
    if parser_name not in ALLOWED_PARSERS:
        raise ValueError(f"Invalid parser name: {parser_name}")

    for argument, value in values_dict.items():
        try:
            type_fn = PARAMETER_TYPE_MAP[parser_name][argument]
            values_dict[argument] = type_fn(value)
        except KeyError:
            pass

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    args_map = {"main": ["--color", "--terminal", "--columns"], "virsh": ["--display", "--verbosity"], "ospd": ["--mode", "--regex"]}
    try:
        for arg in args_map[parser_name]:
            values_dict[arg] = _cast_val(values_dict[arg])
    except:
        pass

def _convert_non_cli_args(self, parser_name: str, values_dict: dict):
    for key, value in values_dict.items():
        if type(value) == str:
            if key in self.known_types:
                if self.known_types[key] in [int, float, bool]:
                    try:
                        values_dict[key] = self.known_types[key](value)
                    except (ValueError, TypeError):
                        raise ValueError(f"Could not convert argument '{key}' to type '{self.known_types[key]}'.")
                else:
                    raise ValueError(f"Unexpected type '{self.known_types[key]}' in known_types dictionary.")
            else:
                raise ValueError(f"Unknown key '{key}' in values_dict dictionary.")
        else:
            raise ValueError(f"Argument '{key}' has already been converted to type '{type(value)}' and cannot be converted again.")

def _convert_non_cli_args(self, parser_name, values_dict):
    if not isinstance(parser_name, str):
        raise ValueError("parser_name must be a string")
    if not isinstance(values_dict, dict):
        raise ValueError("values_dict must be a dictionary")

    for arg, value in values_dict.items():
        if arg in self._get_arg_types(parser_name):
            try:
                values_dict[arg] = self._cast_arg_value(arg, value)
            except ValueError as e:
                raise RuntimeError(f"Failed to cast arg {arg} to correct type: {e}")

    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    # Create an empty dictionary to store the flattened properties
    flattened_dict = {}

    # Get the plugin's spec file
    try:
        spec_file = get_spec_file(plugin_dir)
    except FileNotFoundError as e:
        raise e

    # Load the spec file as a YAML object
    with open(spec_file, "r") as f:
        spec = yaml.safe_load(f)

    # Iterate through the spec dictionary
    for key, value in spec.items():
        if isinstance(value, dict):
            # If the value is a dictionary, recursively call this function with the value as the argument
            flattened_dict.update(get_plugin_spec_flatten_dict(value))
        else:
            # If the value is not a dictionary, add it to the flattened dictionary
            flattened_dict[key] = value

    return flattened_dict

def get_plugin_spec_flatten_dict(plugin_dir) -> Dict:
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """

    # check if the plugin_dir is valid
    if not plugin_dir:
        raise ValueError("Invalid plugin_dir:", plugin_dir)

    # read the plugin's spec file
    spec_file = os.path.join(plugin_dir, "spec.json")
    with open(spec_file, "r") as f:
        plugin_spec = json.load(f)

    # create a flat dict from the plugin_spec
    flatten_dict = {}
    for key, value in plugin_spec.items():
        if isinstance(value, dict):
            for sub_key, sub_value in value.items():
                flatten_dict[f"{key}.{sub_key}"] = sub_value
        else:
            flatten_dict[key] = value

    return flatten_dict

