def get_plugin_spec_flatten_dict(plugin_dir):
    plugin_spec = {}
    # use os.path to walk through the plugin's directory
    for root, dirs, files in os.walk(plugin_dir):
        # skip the plugin's directory itself
        if root == plugin_dir:
            continue
        # iterate over the subdirectories and gather their properties
        for dir in dirs:
            properties = get_dir_dict(os.path.join(root, dir))
            # add each directory's properties to the plugin_spec
            plugin_spec.update(properties)
        # iterate over the files and gather their properties
        for file in files:
            properties = get_file_dict(os.path.join(root, file))
            # add each file's properties to the plugin_spec
            plugin_spec.update(properties)
    # return the flattened dicionary
    return plugin_spec

